      const themeBtn = fig.querySelector('[data-theme-toggle]');
      const statusEl = fig.querySelector('[data-mech-status]');
      const stageBtns = [...fig.querySelectorAll('[data-stage-btn]')];
      const svgStagePills = [...svg.querySelectorAll('.stage-pill')];

      const STAGE_COPY = {
        '': 'Showing all 3 PKCE handshake stages. Select a stage to inspect its exchange.',
        '1': 'Stage 1: Browser App sends an Auth Request with a Code Challenge to Auth Server.',
        '2': 'Stage 2: Auth Server returns an Auth Code to Browser App.',
        '3': 'Stage 3: Browser App sends the Auth Code and Code Verifier to the Token Endpoint, which returns an Access Token.'
      };

      function setPaused(nextPaused, announce) {
        fig.dataset.paused = String(nextPaused);
        toggleBtn.setAttribute('aria-pressed', String(nextPaused));
        toggleBtn.textContent = nextPaused ? 'Play animation' : 'Pause animation';
        if (typeof svg.pauseAnimations === 'function') {
          if (nextPaused) {
            svg.pauseAnimations();
          } else {
            svg.unpauseAnimations();
          }
        }
        if (announce && statusEl) {
          statusEl.textContent = nextPaused
            ? 'Animation paused. Static directional arrows and stage badges remain visible.'
            : 'Animation playing.';
        }
      }

      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      if (prefersReduced) {
        setPaused(true, false);
        statusEl.textContent = 'Reduced motion is active; displaying static directional arrows for all 3 PKCE stages.';
      }

      toggleBtn.addEventListener('click', () => {
        const isPaused = fig.dataset.paused === 'true';
        setPaused(!isPaused, true);
      });

      function setActiveStage(stageId) {
        const nextStage = fig.dataset.activeStage === stageId && stageId !== '' ? '' : stageId;
        fig.dataset.activeStage = nextStage;
        stageBtns.forEach((btn) => {
          btn.setAttribute('aria-pressed', String(btn.dataset.stageBtn === nextStage));
        });
        if (statusEl) {
          statusEl.textContent = STAGE_COPY[nextStage] || STAGE_COPY[''];
        }
      }

      stageBtns.forEach((btn) => {
        btn.addEventListener('click', () => {
          const target = btn.dataset.stageBtn;
          fig.dataset.activeStage = target;
          stageBtns.forEach((b) => {
            b.setAttribute('aria-pressed', String(b.dataset.stageBtn === target));
          });
          statusEl.textContent = STAGE_COPY[target] || STAGE_COPY[''];
        });
      });

      svgStagePills.forEach((pill) => {
        pill.addEventListener('click', () => setActiveStage(pill.dataset.stage));
        pill.addEventListener('keydown', (e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            setActiveStage(pill.dataset.stage);
          } else if (e.key === 'Escape') {
            fig.dataset.activeStage = '';
            stageBtns.forEach((b) => b.setAttribute('aria-pressed', String(b.dataset.stageBtn === '')));
            statusEl.textContent = STAGE_COPY[''];
          }
        });
      });

      function currentTheme() {
        if (root.dataset.theme === 'dark' || root.dataset.theme === 'light') {
          return root.dataset.theme;
        }
        return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
